<script lang="ts">
 import {onMount} from 'svelte';import {Api} from '$lib/api';let settings=$state<any>({});let rr=$state<any>({});let fcc=$state<any>({});let error=$state('');let saved=$state(false);
 async function load(){try{settings=await Api.settings();rr={...(settings.radio_reference??{})};fcc={...(settings.fcc_lookup??{})};error=''}catch(e){error=String(e)}}onMount(load);
 function update(section:'rr'|'fcc',key:string,value:string){const current=section==='rr'?rr:fcc;const old=current[key];const parsed=typeof old==='boolean'?value==='true':typeof old==='number'?Number(value):value;if(section==='rr')rr={...rr,[key]:parsed};else fcc={...fcc,[key]:parsed}}
 async function save(){try{await Api.setSettings({...settings,radio_reference:rr,fcc_lookup:fcc});saved=true;setTimeout(()=>saved=false,1800);await load()}catch(e){error=String(e)}}
</script>
<div class="page"><h1>Frequency Lookups</h1><p class="muted">Configure RadioReference and FCC lookup integrations.</p>{#if error}<p class="error">{error}</p>{/if}{#if saved}<p class="saved">Settings saved</p>{/if}<div class="grid"><section class="card"><h2>RadioReference</h2>{#each Object.entries(rr) as [key,value]}<label><span>{key}</span>{#if typeof value==='boolean'}<select value={String(value)} onchange={(e)=>update('rr',key,e.currentTarget.value)}><option value="true">Enabled</option><option value="false">Disabled</option></select>{:else}<input value={String(value??'')} oninput={(e)=>update('rr',key,e.currentTarget.value)}/>{/if}</label>{:else}<p class="muted">No RadioReference settings present.</p>{/each}</section><section class="card"><h2>FCC Lookup</h2>{#each Object.entries(fcc) as [key,value]}<label><span>{key}</span>{#if typeof value==='boolean'}<select value={String(value)} onchange={(e)=>update('fcc',key,e.currentTarget.value)}><option value="true">Enabled</option><option value="false">Disabled</option></select>{:else}<input value={String(value??'')} oninput={(e)=>update('fcc',key,e.currentTarget.value)}/>{/if}</label>{:else}<p class="muted">No FCC lookup settings present.</p>{/each}</section></div><div class="actions"><button class="primary" onclick={save}>Save settings</button><button onclick={load}>Reload</button></div></div>
<style>.page{padding:16px;overflow-y:auto;height:100%}.muted{color:var(--fg-dim)}.error{color:var(--danger)}.saved{color:var(--ok)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}.card{padding:14px;background:var(--bg-elev);border:1px solid var(--line);border-radius:8px}h2{font-size:15px;color:var(--accent-2)}label{display:grid;grid-template-columns:1fr 1.5fr;gap:9px;align-items:center;margin:8px 0}label span{font:12px var(--mono);word-break:break-word}input,select,button{background:var(--bg);color:var(--fg);border:1px solid var(--line);padding:7px 9px;border-radius:5px}.actions{display:flex;gap:8px;margin-top:12px}.primary{color:var(--accent);border-color:var(--accent)}</style>
